const body = $json.body || $json;
return {
  responseId: body.responseId || ('resp_' + Date.now()),
  employeeId: body.employeeId || 'EMP-2026-08',
  employeeName: body.employeeName || 'Nguyễn Văn A',
  employeeEmail: body.employeeEmail || 'nguyen.vana@company.com',
  department: body.department || 'Phòng Kỹ thuật & AI',
  surveyTitle: body.surveyTitle || 'Khảo sát Hạnh phúc & Gắn kết Q4',
  rating: Number(body.rating || 6),
  textAnswer: body.textAnswer || 'Dạo này dự án chạy nước rút, liên tục OT cuối tuần nên tôi cảm thấy khá mệt mỏi và kiệt sức. Cần sự hỗ trợ cân đối lại khối lượng việc.',
  submittedAt: new Date().toISOString()
};

// Xử lý và phân tích kết quả trả về từ Google Gemini
const inputItem = $input.first().json;
let geminiRaw = '';

if (inputItem?.content?.parts?.[0]?.text) {
  geminiRaw = inputItem.content.parts[0].text;
} else if (inputItem?.content?.text) {
  geminiRaw = inputItem.content.text;
} else if (typeof inputItem?.content === 'string') {
  geminiRaw = inputItem.content;
} else if (typeof inputItem?.text === 'string') {
  geminiRaw = inputItem.text;
}

let parsed = null;
try {
  const jsonMatch = geminiRaw.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsed = JSON.parse(jsonMatch[0]);
  }
} catch (e) {
  parsed = null;
}

// Lấy thông tin bài khảo sát gốc từ node Chuẩn Hóa
const original = $('Chuẩn Hóa & Tiền Xử Lý Dữ Liệu').first().json;
const text = (original.textAnswer || '').toLowerCase();

let category = parsed?.category || 'WORKLOAD_STRESS';
let sentimentScore = parsed?.sentimentScore !== undefined ? parsed.sentimentScore : -0.65;
let burnoutRisk = parsed?.burnoutRisk || 'HIGH';
let riskLevel = parsed?.riskLevel || 'CAO';
let actionRecommendation = parsed?.actionRecommendation || 'Cần hỗ trợ điều phối lại công việc và bố trí buổi trò chuyện 1-on-1.';

if (!parsed) {
  if (text.includes('lương') || text.includes('thưởng') || text.includes('tiền')) {
    category = 'COMPENSATION_BENEFITS';
    sentimentScore = -0.4;
    burnoutRisk = 'MEDIUM';
    riskLevel = 'VỪA';
    actionRecommendation = 'HR xem xét lại thang bảng lương và giải thích chính sách đãi ngộ.';
  } else if (text.includes('vui') || text.includes('hài lòng') || original.rating >= 8) {
    category = 'CULTURE_ENVIRONMENT';
    sentimentScore = 0.85;
    burnoutRisk = 'LOW';
    riskLevel = 'THẤP';
    actionRecommendation = 'Ghi nhận đóng góp tích cực và lan tỏa tinh thần gắn kết.';
  }
}

return {
  ...original,
  aiAnalysis: {
    engine: 'Google Gemini 1.5 Flash',
    category,
    sentimentScore,
    burnoutRisk,
    riskLevel,
    isUrgent: (burnoutRisk === 'HIGH' || burnoutRisk === 'CRITICAL'),
    actionRecommendation,
    analyzedAt: new Date().toISOString()
  }
};

